//! `--self-test`: proves that mpv video is drawn under the Slint UI.
//!
//! Plays SMPTE color bars generated by FFmpeg (no media file needed), waits
//! until playback is running, snapshots the window and checks that the bars
//! are visible, the right way up, and that the Slint button is drawn on top.
//! Both the window's own framebuffer and Slint's `take_snapshot` (which
//! renders to a texture) are checked, since they take different GL paths.

use std::cell::Cell;
use std::process::ExitCode;
use std::rc::Rc;
use std::sync::Arc;
use std::time::{Duration, Instant};

use enthuse_player::Player;
use slint::{ComponentHandle, Rgba8Pixel, SharedPixelBuffer};

use crate::SpikeWindow;
use crate::video::ScreenCapture;

/// 4:3 like the window, so the video fills it without letterboxing.
pub const SOURCE: &str = "av://lavfi:smptebars=size=640x480:rate=30";

const TIMEOUT: Duration = Duration::from_secs(30);
const MIN_PLAYBACK_SECS: f64 = 0.5;

/// Result of the self-test, shared with the timer that runs it.
#[derive(Clone, Default)]
pub struct Outcome(Rc<Cell<Option<bool>>>);

impl Outcome {
    pub fn exit_code(&self) -> ExitCode {
        match self.0.get() {
            Some(true) => ExitCode::SUCCESS,
            // Not run (normal mode) counts as success.
            None => ExitCode::SUCCESS,
            Some(false) => ExitCode::FAILURE,
        }
    }
}

pub fn start(window: &SpikeWindow, player: Arc<dyn Player>, capture: ScreenCapture) -> Outcome {
    let outcome = Outcome::default();
    let result = outcome.clone();
    let started = Instant::now();
    let weak = window.as_weak();
    let mut screen_requested = false;

    // Keep the timer alive for the whole event loop.
    let timer = Rc::new(slint::Timer::default());
    let keep = timer.clone();
    timer.start(
        slint::TimerMode::Repeated,
        Duration::from_millis(100),
        move || {
            let _ = &keep;
            let Some(window) = weak.upgrade() else { return };
            if result.0.get().is_some() {
                return; // Already finished; waiting for the event loop to quit.
            }
            let finish = |ok: bool| {
                result.0.set(Some(ok));
                println!("self-test: {}", if ok { "PASS" } else { "FAIL" });
                let _ = slint::quit_event_loop();
            };

            if started.elapsed() > TIMEOUT {
                eprintln!("self-test: timed out waiting for playback");
                finish(false);
                return;
            }
            let pos = player.position().unwrap_or(0.0);
            if pos < MIN_PLAYBACK_SECS {
                return;
            }

            // First grab the window's own framebuffer on the next redraw.
            if !screen_requested {
                capture.request();
                window.window().request_redraw();
                screen_requested = true;
                return;
            }
            let Some(screen) = capture.take() else {
                return; // Not rendered yet.
            };

            let mut failures: Vec<String> = check(&screen)
                .into_iter()
                .map(|f| format!("window framebuffer: {f}"))
                .collect();
            match window.window().take_snapshot() {
                Ok(snapshot) => failures.extend(
                    check(&snapshot)
                        .into_iter()
                        .map(|f| format!("snapshot: {f}")),
                ),
                Err(err) => failures.push(format!("snapshot failed: {err}")),
            }
            for f in &failures {
                eprintln!("self-test: {f}");
            }
            finish(failures.is_empty());
        },
    );
    outcome
}

/// Expected color at a point given as fractions of the window size.
struct Probe {
    what: &'static str,
    x: f32,
    y: f32,
    rgb: [u8; 3],
}

// SMPTE bars (75%): top two thirds are 7 bars, then a thin strip whose first
// block is blue. If the video were upside down, the top probes would land in
// the dark bottom section instead.
const VIDEO_PROBES: &[Probe] = &[
    Probe {
        what: "gray bar",
        x: 1.0 / 14.0,
        y: 0.3,
        rgb: [191, 191, 191],
    },
    Probe {
        what: "yellow bar",
        x: 3.0 / 14.0,
        y: 0.3,
        rgb: [191, 191, 0],
    },
    Probe {
        what: "cyan bar",
        x: 5.0 / 14.0,
        y: 0.3,
        rgb: [0, 191, 191],
    },
    Probe {
        what: "magenta bar",
        x: 9.0 / 14.0,
        y: 0.3,
        rgb: [191, 0, 191],
    },
    Probe {
        what: "blue strip",
        x: 1.0 / 14.0,
        y: 0.71,
        rgb: [0, 0, 191],
    },
];

/// Color tolerance per channel: YUV conversion and scaling shift colors a bit.
const TOLERANCE: i32 = 48;

/// Button center in logical pixels from the bottom-right corner (see spike.slint).
const BUTTON_FROM_RIGHT: f32 = 60.0;
const BUTTON_FROM_BOTTOM: f32 = 50.0;
const BUTTON_RGB: [u8; 3] = [0xff, 0x00, 0x80];

fn check(snapshot: &SharedPixelBuffer<Rgba8Pixel>) -> Vec<String> {
    let (w, h) = (snapshot.width(), snapshot.height());
    let pixels = snapshot.as_slice();
    let at = |x: u32, y: u32| {
        let p = pixels[(y.min(h - 1) * w + x.min(w - 1)) as usize];
        [p.r, p.g, p.b]
    };
    let close = |a: [u8; 3], b: [u8; 3]| {
        a.iter()
            .zip(b)
            .all(|(a, b)| (*a as i32 - b as i32).abs() <= TOLERANCE)
    };

    let mut failures = Vec::new();
    for p in VIDEO_PROBES {
        let got = at((p.x * w as f32) as u32, (p.y * h as f32) as u32);
        if !close(got, p.rgb) {
            failures.push(format!(
                "{}: expected about {:?}, got {:?}",
                p.what, p.rgb, got
            ));
        }
    }

    // Snapshots are in physical pixels; derive the scale from the 640px-wide layout
    // only if the window kept its preferred size, otherwise assume scale 1.
    let scale = (w as f32 / 640.0).max(1.0);
    let bx = w as f32 - BUTTON_FROM_RIGHT * scale;
    let by = h as f32 - BUTTON_FROM_BOTTOM * scale;
    let got = at(bx as u32, by as u32);
    if !close(got, BUTTON_RGB) {
        failures.push(format!(
            "button over video: expected about {BUTTON_RGB:?}, got {got:?}"
        ));
    }
    println!(
        "self-test: snapshot {w}x{h}, checked {} points",
        VIDEO_PROBES.len() + 1
    );
    failures
}
